-- Reseed the capabilities map and ordered allowed_statuses on the system rows.
-- Generated by scripts/generate-work-item-type-seed.ts — do not edit by hand.
-- Re-run the script to regenerate after editing TYPE_SPECS.
--
-- UPDATEs (not INSERTs): the rows already exist. This sets the capabilities
-- map deriveRules unpacks and reorders allowed_statuses so the intended
-- initial status is first (deriveRules reads allowedStatuses[0]).

UPDATE "work_item_type" SET
  "capabilities" = $wit$
{"canHaveParent":true,"requiresParent":true,"canHaveChildren":true,"isHierarchyNode":false,"planEligible":true,"hasSetInitialStatus":false}
$wit$::jsonb,
  "allowed_statuses" = $wit$
["BACKLOG","GENERATED","REFINING_DESCRIPTION","REFINING_DETAILS","REFINING_ACCEPTANCE_CRITERIA","GENERATING_DESCRIPTION","GENERATING_DETAILS","GENERATING_DESCRIPTION_AND_DETAILS","GENERATING_ACCEPTANCE_CRITERIA","GENERATING_ALL","ACTIVE","ON_HOLD","VERIFYING","COMPLETED","CANCELLED","ARCHIVED","SUPERSEDED"]
$wit$::jsonb,
  "updated_at" = CURRENT_TIMESTAMP
WHERE "id" = 'c1a70000-0000-0000-0000-000000000001';

